const GLYPH_MIN_PX: usize = 16;
const GLYPH_MAX_PX: usize = 128;

// Returns native pixels, never an upscaled bitmap. Above 400% the 128px glyph
// remains centered at 1:1 rather than introducing GDI scaling blur.
fn glyph_pixels(index: usize, target: i32) -> Option<(usize, Vec<u8>)> {
    if target <= 0 { return None; }
    let size = (target as usize).clamp(GLYPH_MIN_PX, GLYPH_MAX_PX);
    let (data, sizes) = match index {
        0 => (DISPLAY_RLE, DISPLAY_SIZES),
        1 => (VOICE_CALL_RLE, VOICE_CALL_SIZES),
        2 => (CAMERA_RLE, CAMERA_SIZES),
        3 => (CALL_END_RLE, CALL_END_SIZES),
        4 => (CLOSE_RLE, CLOSE_SIZES),
        _ => return None,
    };
    let (offset, len) = sizes[size - GLYPH_MIN_PX];
    let mut pixels = Vec::with_capacity(size * size * 4);
    for run in data[offset..offset + len].chunks_exact(2) {
        for _ in 0..run[0] { pixels.extend_from_slice(&[run[1]; 4]); }
    }
    if pixels.len() != size * size * 4 { return None; }
    Some((size, pixels))
}

#[cfg(test)]
mod glyph_tests {
    use super::*;
    #[test]
    fn every_physical_size_is_native_white_premultiplied_bgra() {
        for index in 0..5 {
            for target in 16..=128 {
                let (size, bytes) = glyph_pixels(index, target).unwrap();
                assert_eq!(size, target as usize);
                assert_eq!(bytes.len(), size * size * 4);
                assert!(bytes.chunks_exact(4).all(|p| p == [p[3]; 4]));
                assert!(bytes.chunks_exact(4).any(|p| p[3] > 0 && p[3] < 255));
                assert!(bytes.chunks_exact(4).any(|p| p[3] >= 128));
                assert!(bytes[..size * 4].iter().all(|v| *v == 0));
            }
        }
    }
    #[test]
    fn rejects_invalid_request_and_caps_without_upscaling() {
        assert!(glyph_pixels(5,32).is_none());
        assert!(glyph_pixels(0,0).is_none());
        assert!(glyph_pixels(0,-1).is_none());
        assert_eq!(glyph_pixels(0,200).unwrap().0,128);
        assert_eq!(glyph_pixels(0,1).unwrap().0,16);
    }
}
